INSERT INTO project_areas_of_expertise (project_id, area_of_expertise_id)
SELECT projects.id, areas_of_expertise.id
FROM (
         VALUES
             ('Projeto Seed Administração', 'Escola de Negócios'),
             ('Projeto Seed Ciências Contábeis', 'Escola de Negócios'),
             ('Projeto Seed Arquitetura & Urbanismo', 'Escola de Design & Arquitetura'),
             ('Projeto Seed Design', 'Escola de Design & Arquitetura'),
             ('Projeto Seed Biomedicina', 'Escola de Saúde'),
             ('Projeto Seed Enfermagem', 'Escola de Saúde'),
             ('Projeto Seed Nutrição', 'Escola de Saúde'),
             ('Projeto Seed Psicologia', 'Escola de Saúde'),
             ('Projeto Seed Direito', 'Escola de Direito'),
             ('Projeto Seed Engenharia Civil', 'Escola Politécnica'),
             ('Projeto Seed Engenharia Elétrica', 'Escola Politécnica'),
             ('Projeto Seed Engenharia Mecânica', 'Escola Politécnica'),
             ('Projeto Seed Engenharia de Produção', 'Escola Politécnica'),
             ('Projeto Seed Engenharia de Software', 'Escola Politécnica')
     ) AS data(project_name, area_name)
     JOIN projects ON projects.name = data.project_name
     JOIN areas_of_expertise ON areas_of_expertise.name = data.area_name
    ON CONFLICT (project_id, area_of_expertise_id) DO NOTHING;

